import argparse
import csv
import json


def find_col(fieldnames, candidates):
    if not fieldnames:
        return None
    lower_map = {fn.lower(): fn for fn in fieldnames}
    for cand in candidates:
        if cand.lower() in lower_map:
            return lower_map[cand.lower()]
    return None


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("payload")
    args = parser.parse_args()
    payload = json.loads(args.payload)

    orders_path = payload.get("orders_path", "/inputs/orders.csv")
    customers_path = payload.get("customers_path", "/inputs/customers.csv")

    customers = {}
    with open(customers_path, newline="") as f:
        reader = csv.DictReader(f)
        fieldnames = reader.fieldnames or []
        region_col = find_col(fieldnames, ["region", "customer_region"])
        if region_col is None and len(fieldnames) >= 2:
            region_col = fieldnames[1]
        cid_col = find_col(fieldnames, ["customer_id", "customerid", "cust_id", "id"])
        for row in reader:
            cid = (row.get(cid_col, "") if cid_col else "").strip()
            region = (row.get(region_col, "") if region_col else "").strip().lower()
            if cid:
                customers[cid] = region

    total = 0.0
    with open(orders_path, newline="") as f:
        reader = csv.DictReader(f)
        fieldnames = reader.fieldnames or []
        amount_col = find_col(fieldnames, ["amount", "order_amount", "total_amount", "total", "price", "value"])
        if amount_col is None:
            amount_col = "amount"
        cid_col = find_col(fieldnames, ["customer_id", "customerid", "cust_id"])
        if cid_col is None:
            cid_col = "customer_id"

        for row in reader:
            cid = (row.get(cid_col, "") or "").strip()
            if cid in customers and customers[cid] == "west":
                raw = (row.get(amount_col, "") or "0").replace("$", "").replace(",", "").strip()
                try:
                    total += float(raw)
                except ValueError:
                    pass

    if total == int(total):
        print(int(total))
    else:
        print(total)


if __name__ == "__main__":
    main()

import argparse
import csv
import json
from decimal import Decimal, InvalidOperation


def parse_amount(s):
    s = s.strip()
    if not s:
        return None
    negative = False
    if s.startswith("(") and s.endswith(")"):
        negative = True
        s = s[1:-1]
    s = s.replace("$", "").replace(",", "").strip()
    if s.endswith("-"):
        negative = True
        s = s[:-1]
    if not s:
        return None
    try:
        value = Decimal(s)
    except InvalidOperation:
        return None
    if negative:
        value = -value
    return value


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("payload")
    args = parser.parse_args()
    payload = json.loads(args.payload)
    path = payload["path"]

    total = Decimal("0")
    with open(path, "r", newline="") as f:
        reader = csv.reader(f)
        rows = list(reader)

    if not rows:
        print("0.00")
        return

    header = rows[0]
    amount_idx = None
    for i, col in enumerate(header):
        if col.strip().lower() == "amount":
            amount_idx = i
            break
    if amount_idx is None:
        amount_idx = len(header) - 1

    for row in rows[1:]:
        if amount_idx >= len(row):
            continue
        cell = row[amount_idx]
        if not cell.strip():
            continue
        parsed = parse_amount(cell)
        if parsed is not None:
            total += parsed

    print(f"{total:.2f}")


if __name__ == "__main__":
    main()

import argparse
import json
import csv


def parse_amount(s):
    if s is None:
        return None
    s = s.strip().replace("$", "").replace(",", "").strip()
    if not s:
        return None
    if s.startswith("-"):
        return -float(s[1:])
    return float(s)


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("payload")
    args = parser.parse_args()
    payload = json.loads(args.payload)
    path = payload["path"]

    total = 0.0
    with open(path, newline="") as f:
        reader = csv.DictReader(f)
        for row in reader:
            value = parse_amount(row.get("amount", ""))
            if value is None:
                continue
            total += value

    print(f"{total:.2f}")


if __name__ == "__main__":
    main()

import argparse
import csv
import datetime
import json
import re

DATE_RE = re.compile(r"^\d{4}-\d{2}-\d{2}$")


def parse_iso(value):
    value = value.strip()
    if not DATE_RE.match(value):
        return None
    try:
        return datetime.date.fromisoformat(value)
    except ValueError:
        return None


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("payload")
    args = parser.parse_args()
    payload = json.loads(args.payload)
    path = payload["path"]

    with open(path, newline="", encoding="utf-8") as f:
        rows = list(csv.reader(f))

    if not rows:
        print("0")
        return

    header = rows[0]
    data = rows[1:]

    # Find the date column: pick the column whose non-empty values are most
    # often valid YYYY-MM-DD dates.
    best_col = None
    best_count = 0
    for col_idx in range(len(header)):
        count = 0
        for row in data:
            if col_idx < len(row):
                d = parse_iso(row[col_idx])
                if d is not None:
                    count += 1
        if count > best_count:
            best_count = count
            best_col = col_idx

    dates = []
    if best_col is not None and best_count > 0:
        for row in data:
            if best_col < len(row):
                d = parse_iso(row[best_col])
                if d is not None:
                    dates.append(d)
    else:
        # Fallback: scan every cell.
        for row in data:
            for cell in row:
                d = parse_iso(cell)
                if d is not None:
                    dates.append(d)

    if len(dates) < 2:
        print("0")
        return

    diff_days = (max(dates) - min(dates)).days
    print(str(diff_days))


if __name__ == "__main__":
    main()

import argparse
import csv
import json

def parse_amount(s):
    s = s.strip()
    if not s:
        return 0.0
    s = s.replace('$', '').replace(',', '')
    try:
        return float(s)
    except ValueError:
        return 0.0

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("payload")
    args = parser.parse_args()
    payload = json.loads(args.payload)
    path = payload["path"]

    total = 0.0
    with open(path, 'r', newline='') as f:
        reader = csv.reader(f)
        rows = list(reader)

    if not rows:
        print(f"{total:.2f}")
        return

    header = rows[0]
    amount_col = -1
    for i, h in enumerate(header):
        if h.strip().lower() == 'amount':
            amount_col = i
            break

    if amount_col == -1:
        amount_col = len(header) - 1

    for row in rows[1:]:
        if not row or all(not cell.strip() for cell in row):
            continue
        if amount_col < len(row):
            total += parse_amount(row[amount_col])

    print(f"{total:.2f}")

if __name__ == "__main__":
