import argparse
import csv
import json

def parse_amount(s):
    s = s.strip()
    if not s:
        return None
    negative = False
    if s.startswith('(') and s.endswith(')'):
        negative = True
        s = s[1:-1]
    s = s.replace('$', '').replace(',', '').strip()
    if s.startswith('-'):
        negative = not negative
        s = s[1:]
    if not s:
        return None
    try:
        value = float(s)
    except ValueError:
        return None
    if negative:
        value = -value
    return value

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("payload")
    args = parser.parse_args()
    payload = json.loads(args.payload)
    path = payload["path"]

    total = 0.0
    with open(path, 'r', newline='') as f:
        reader = csv.reader(f)
        try:
            header = next(reader)
        except StopIteration:
            print(f"{total:.2f}")
            return

        amount_col = None
        for i, col in enumerate(header):
            if col.strip().lower() == 'amount':
                amount_col = i
                break

        if amount_col is None:
            for i, col in enumerate(header):
                if 'amount' in col.strip().lower():
                    amount_col = i
                    break

        if amount_col is None:
            amount_col = len(header) - 1

        for row in reader:
            if not row:
                continue
            if all(not cell.strip() for cell in row):
                continue
            if amount_col >= len(row):
                continue
            value = parse_amount(row[amount_col])
            if value is not None:
                total += value

    print(f"{total:.2f}")

if __name__ == "__main__":
    main()

import argparse
import csv
import json
from datetime import datetime


def looks_like_date(s):
    try:
        datetime.strptime(s.strip(), "%Y-%m-%d")
        return True
    except (ValueError, AttributeError):
        return False


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("payload")
    args = parser.parse_args()
    payload = json.loads(args.payload)
    path = payload["path"]

    dates = []
    with open(path, "r", newline="") as f:
        reader = csv.reader(f)
        rows = [r for r in reader if r]

    if not rows:
        print("0")
        return

    # Detect header: if the first cell of the first row is not a date,
    # treat the first row as a header and look for a 'date' column.
    if not looks_like_date(rows[0][0]):
        date_col = 0
        data_rows = rows[1:]
        for i, h in enumerate(rows[0]):
            if h.strip().lower() == "date":
                date_col = i
                break
    else:
        date_col = 0
        data_rows = rows

    for row in data_rows:
        if date_col >= len(row):
            continue
        val = row[date_col].strip()
        if not val:
            continue
        try:
            dates.append(datetime.strptime(val, "%Y-%m-%d"))
        except ValueError:
            continue

    if not dates:
        print("0")
        return

    print((max(dates) - min(dates)).days)


if __name__ == "__main__":
    main()
